/**
 * Generate Supabase `Database` types from the linked project.
 * Usage: npm run db:gen-types
 * Output: src/types/database.ts (do not edit by hand).
 */
import { execSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const outPath = resolve(root, "src/types/database.ts");
const banner =
  "/** Generated by `npm run db:gen-types` from the linked project. Do not edit by hand. */\n";

const generated = execSync(
  "npx supabase gen types --linked --lang typescript --schema public",
  { cwd: root, encoding: "utf8", maxBuffer: 80 * 1024 * 1024 }
);
const body = generated.startsWith("\uFEFF") ? generated.slice(1) : generated;
writeFileSync(outPath, banner + body, "utf8");
console.log(`wrote ${outPath} (${body.split("\n").length} lines)`);
